#!/bin/bash

# This script translates Chinese commit messages to English using git filter-branch

# Create a temporary script for git filter-branch
TEMP_FILTER_MSG=$(mktemp)

# Write the message filter script
cat > "$TEMP_FILTER_MSG" << 'FILTER_SCRIPT'
#!/bin/bash

# Commit translation mapping
case "$GIT_COMMIT" in
    94af842)
        echo "fix(database): fix database migration issues"
        ;;
    52212a6)
        echo "fix(ui): fix unread capsule flash and white line display"
        ;;
    034dc02)
        echo "fix(network): fix port mapping issues"
        ;;
    394bc2e)
        echo "feat(search): optimize global search - Slack-style search, keyword highlight, message jump"
        ;;
    9eb7268)
        echo "test: add MCP and API test scripts"
        ;;
    52ed5f8)
        echo "refactor(unread): modify unread message jump logic"
        ;;
    537257e)
        echo "fix(mention): fix @mention showing user ID instead of username in notifications"
        ;;
    bfee3ea)
        echo "feat(search): improve search positioning user experience"
        ;;
    eb6fff3)
        echo "refactor(input): optimize input box display"
        ;;
    7201f74)
        echo "feat(thread): improve thread popup text display"
        ;;
    13668b4)
        echo "refactor(image): optimize image rendering and extract utility module"
        ;;
    276f6bb)
        echo "fix(cors): fix FileList and AttachmentCard download link CORS issues"
        ;;
    38bf249)
        echo "fix(proxy): fix thumbnailUrl proxy requirement"
        ;;
    c16064f)
        echo "fix(proxy): add file proxy for OSS CORS"
        ;;
    85e3a61)
        echo "fix(api): fix message API returning full attachment data"
        ;;
    4c23f47)
        echo "feat(mention): support Slack @mention showing username"
        ;;
    2687930)
        echo "fix(test): fix test bugs"
        ;;
    1833bca)
        echo "fix(websocket): fix WebSocket issues"
        ;;
    548fbd0)
        echo "feat(database): support database reset and modify default credentials"
        ;;
    b555542)
        echo "fix(database): fix password hash format"
        ;;
    492f41e)
        echo "refactor(database): update initial migration logic"
        ;;
    10d3652)
        echo "feat(mcp): add channel_permission MCP"
        ;;
    6704901)
        echo "refactor(mcp): improve MCP and database operations"
        ;;
    9ea8de4)
        echo "feat(i18n): language modification and file support"
        ;;
    e6df72a)
        echo "chore: remove unused Electron desktop app code"
        ;;
    150e205)
        echo "feat: add multi-instance Docker deployment support"
        ;;
    ee23724)
        echo "docs: update README with comprehensive English documentation"
        ;;
    32f8d06)
        echo "fix(mcp): MCP server support HOST env var"
        ;;
    e6f7348)
        echo "fix(build): exclude mcp-server from Next.js build"
        ;;
    07e701d)
        echo "fix(docker): remove mcp-server from .dockerignore"
        ;;
    141d1b1)
        echo "fix(docker): fix Docker build cache conflict"
        ;;
    4504be9)
        echo "fix(build): use nixpacks cmds array for MCP build"
        ;;
    e65a355)
        echo "fix(mcp): configure MCP server port via MCP_PORT"
        ;;
    a1f8b91)
        echo "fix(build): fix nixpacks.toml build command format"
        ;;
    229a092)
        echo "feat(deploy): start MCP server with main app"
        ;;
    4018aaa)
        echo "refactor(oss): lazy initialize OSS client"
        ;;
    c674185)
        echo "feat(mcp): add HTTP to HTTPS redirect for MCP server"
        ;;
    9dfce16)
        echo "feat(mcp): add INTERNAL_API_URL env var for MCP server"
        ;;
    d4de807)
        echo "debug: add request logging middleware"
        ;;
    10cf770)
        echo "feat(mcp): MCP server support custom internal API URL"
        ;;
    9f3270a)
        echo "fix(esm): fix __dirname in ESM modules"
        ;;
    21e86c7)
        echo "chore(deps): update dependency configuration"
        ;;
    98947ee)
        echo "feat(mcp): improve MCP deployment config and database schema"
        ;;
    fd88dca)
        echo "fix(search): fix user search bug"
        ;;
    9e637e1)
        echo "style(mcp): optimize MCP server startup log output"
        ;;
    4c2e38d)
        echo "feat(traefik): add Let's Encrypt auto HTTPS certificate support"
        ;;
    18745ef)
        echo "feat(mcp): add MCP server HTTP mode deployment"
        ;;
    4a8c442)
        echo "fix(mcp): optimize MCP test page UI"
        ;;
    b02f1ab)
        echo "feat(mcp): integrate MCP server and optimize message list"
        ;;
    79c32e7)
        echo "chore(docker): update Docker config and clean dependencies"
        ;;
    *)
        cat
        ;;
esac
FILTER_SCRIPT

chmod +x "$TEMP_FILTER_MSG"

echo "Running git filter-branch to translate commit messages..."
git filter-branch -f --msg-filter "$TEMP_FILTER_MSG" -- 44a8980..HEAD

# Cleanup
rm -f "$TEMP_FILTER_MSG"

echo "Done! Verifying results..."
git log --oneline 44a8980..HEAD | head -55

